--
-- Table structure for table `tbl_pendaftaran_open_trip`
--

DROP TABLE IF EXISTS `tbl_pendaftaran_open_trip`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tbl_pendaftaran_open_trip` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `travel_package_id` bigint unsigned DEFAULT NULL,
  `nama_paket` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `whatsapp` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jumlah_peserta` smallint unsigned NOT NULL DEFAULT '1',
  `pendamping_gratis` smallint unsigned NOT NULL DEFAULT '0',
  `harga_jual` bigint unsigned DEFAULT NULL,
  `harga_modal` bigint unsigned DEFAULT NULL,
  `biaya_tetap` bigint unsigned NOT NULL DEFAULT '0',
  `potongan_promo` int unsigned NOT NULL DEFAULT '0',
  `kode_rujukan` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `potongan_rujukan` int unsigned NOT NULL DEFAULT '0',
  `imbalan_rujukan` int unsigned NOT NULL DEFAULT '0',
  `imbalan_dibayar_pada` timestamp NULL DEFAULT NULL,
  `daftar_peserta` json DEFAULT NULL,
  `riwayat_penggantian` json DEFAULT NULL,
  `surat_penggantian` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `surat_penggantian_pada` timestamp NULL DEFAULT NULL,
  `tanggal_berangkat` date DEFAULT NULL,
  `titik_jemput` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'baru',
  `pengingat_pelunasan_pada` timestamp NULL DEFAULT NULL,
  `briefing_pada` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tbl_pendaftaran_open_trip_kode_unique` (`kode`),
  KEY `tbl_pendaftaran_open_trip_status_index` (`status`),
  KEY `idx_pendaftaran_paket_status` (`travel_package_id`,`status`),
  KEY `idx_pendaftaran_status_dibuat` (`status`,`created_at`),
  KEY `tbl_pendaftaran_open_trip_kode_rujukan_index` (`kode_rujukan`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

