INSERT INTO `tbl_testimoni` VALUES (1,'Budi Santoso',5,'Pelayanan sangat memuaskan! Tour guide ramah dan destinasi wisata sangat menarik. Recommended!','/storage/testimoni/06cf7beb-884b-4d96-8b7a-a694799771d6.webp','tayang',NULL,'2026-08-14 13:10:35','2026-08-25 14:54:34'),(2,'Siti Nurhaliza',5,'Pengalaman liburan terbaik bersama keluarga. Semua sudah diatur dengan baik, tinggal enjoy saja!',NULL,'tayang',NULL,'2026-08-14 13:10:35','2026-08-14 13:10:35'),(3,'Andi Wijaya',5,'Harga terjangkau dengan fasilitas premium. Driver sopan dan hotel nyaman. Pasti akan booking lagi!',NULL,'tayang',NULL,'2026-08-14 13:10:35','2026-08-14 13:10:35'),(4,'Dewi Lestari',4,'Tour sangat menyenangkan, cuma agak terburu-buru di beberapa spot. Overall bagus!',NULL,'tayang',NULL,'2026-08-14 13:10:35','2026-08-14 13:10:35'),(5,'Rudi Hartono',5,'Destinasi wisata lengkap, makanan enak, guide berpengalaman. Worth it banget!',NULL,'tayang',NULL,'2026-08-14 13:10:35','2026-08-14 13:10:35'),(6,'Muhammad Alamsyah Subekti',5,'agent yang bagus, ikut open trip ga nyesel semua terlayani dengan baik. tour leader nya ramah juga kendaraan terawat, makan selalu on time saat trip juga tidak di buru-buru','/storage/testimoni/365512ca-7f77-4308-92d2-5c15f1afbaa5.webp','tayang',NULL,'2026-08-25 15:15:46','2026-08-25 15:15:46');
/*!40000 ALTER TABLE `tbl_testimoni` ENABLE KEYS */;
UNLOCK TABLES;

